/*
 * prog30_escape_unescape.c
 *
 * Re‑implementation of the original binary’s functionality.
 * The program accepts three command‑line arguments:
 *
 *   prog30_escape_unescape <mode> <string>
 *
 * <mode> must be either "escape" or "unescape".
 *
 *   escape   – converts special characters in <string> to C‑style
 *              escape sequences (\\, \n, \t, \").
 *
 *   unescape – performs the inverse transformation, turning recognised
 *              escape sequences back into the original characters.
 *
 * If the number of arguments is wrong the program prints "USAGE".
 * If the mode is not recognised it prints "INVALID_MODE".
 * If the input string is longer than 1023 characters it prints "INVALID".
 *
 * The transformed string is printed with puts().
 *
 * The implementation follows the logic uncovered in the disassembly;
 * it does **not** attempt to reproduce the obfuscated control flow,
 * only the observable behaviour.
 */

#include <stdio.h>
#include <string.h>
#include <stddef.h>

#define MAX_INPUT_LEN 1023   /* 0x3ff */

static void escape_string(const char *src, char *dst)
{
    size_t i = 0, j = 0;
    while (src[i] != '\0') {
        unsigned char c = (unsigned char)src[i];
        switch (c) {
            case '\\':
                dst[j++] = '\\';
                dst[j++] = '\\';
                break;
            case '\n':
                dst[j++] = '\\';
                dst[j++] = 'n';
                break;
            case '\t':
                dst[j++] = '\\';
                dst[j++] = 't';
                break;
            case '"':
                dst[j++] = '\\';
                dst[j++] = '"';
                break;
            default:
                dst[j++] = c;
                break;
        }
        ++i;
    }
    dst[j] = '\0';
}

static void unescape_string(const char *src, char *dst)
{
    size_t i = 0, j = 0;
    while (src[i] != '\0') {
        if (src[i] == '\\') {
            char nxt = src[i + 1];
            if (nxt == '\\') {
                dst[j++] = '\\';
                i += 2;
            } else if (nxt == 'n') {
                dst[j++] = '\n';
                i += 2;
            } else if (nxt == 't') {
                dst[j++] = '\t';
                i += 2;
            } else if (nxt == '"') {
                dst[j++] = '"';
                i += 2;
            } else {
                /* Unknown escape – keep the backslash as‑is */
                dst[j++] = '\\';
                ++i;
            }
        } else {
            dst[j++] = src[i++];
        }
    }
    dst[j] = '\0';
}

int main(int argc, char **argv)
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *mode   = argv[1];
    const char *input  = argv[2];

    if (strlen(input) > MAX_INPUT_LEN) {
        puts("INVALID");
        return 0;
    }

    /* buffer large enough for the worst‑case expansion (every char becomes two) */
    char out[2 * (MAX_INPUT_LEN + 1)];

    if (strcmp(mode, "escape") == 0) {
        escape_string(input, out);
        puts(out);
    } else if (strcmp(mode, "unescape") == 0) {
        unescape_string(input, out);
        puts(out);
    } else {
        puts("INVALID_MODE");
    }

    return 0;
}
